class Solution {
public:
    int sumOfDigits(vector<int>& nums) {
        int m = *min_element(nums.begin(), nums.end());
        int digit_sum = 0;
        while (m > 0) {
            digit_sum += m % 10;
            m /= 10;
        }
        return digit_sum % 2 == 0 ? 1 : 0;
    }
};

class Solution {
    public int sumOfDigits(int[] nums) {
        int m = nums[0];
        for (int x : nums) m = Math.min(m, x);
        int digitSum = 0;
        while (m > 0) {
            digitSum += m % 10;
            m /= 10;
        }
        return digitSum % 2 == 0 ? 1 : 0;
    }
}

var sumOfDigits = function(nums) {
    let m = Math.min(...nums);
    let digitSum = 0;
    while (m > 0) {
        digitSum += m % 10;
        m = Math.floor(m / 10);
    }
    return digitSum % 2 === 0 ? 1 : 0;
};
